import{_ as a,o as c,c as o,a0 as t}from"./chunks/framework.jwovEGr5.js";const _=JSON.parse('{"title":"Excel表格滚动条过短，一拖就飞出去","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"电脑知识/办公软件/Excel表滚动条过短.md","filePath":"电脑知识/办公软件/Excel表滚动条过短.md"}'),d={name:"电脑知识/办公软件/Excel表滚动条过短.md"};function s(l,e,n,p,i,r){return c(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="excel表格滚动条过短-一拖就飞出去" tabindex="-1">Excel表格滚动条过短，一拖就飞出去 <a class="header-anchor" href="#excel表格滚动条过短-一拖就飞出去" aria-label="Permalink to &quot;Excel表格滚动条过短，一拖就飞出去&quot;">​</a></h1><h2 id="产生问题的可能原因" tabindex="-1">产生问题的可能原因 <a class="header-anchor" href="#产生问题的可能原因" aria-label="Permalink to &quot;产生问题的可能原因&quot;">​</a></h2><p>当我们不小心对太过边缘的位置进行了操作之后，Excel表有时会残留格式、边框、复制痕迹</p><p>例如缩放的过程就可能产生格式残留</p><p>此时，Excel把它们当成“已经使用的区域”，所以把滚动范围扩展到很靠边缘，这就导致了我们在滑动滚动条的时候精度过低，不方便操作</p><h2 id="快捷操作" tabindex="-1">快捷操作 <a class="header-anchor" href="#快捷操作" aria-label="Permalink to &quot;快捷操作&quot;">​</a></h2><p>选中<code>列</code>，按下<code>Ctrl</code>+<code>Shift</code>+<code>→</code>键，可以一键选中该列右侧所有的区域（包含该列）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>此时，右侧所有的内容、格式等等都会被清除</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但是行列的填充色不会消失</span></span></code></pre></div><p>同理，选中<code>行</code>，按下<code>Ctrl</code>+<code>Shift</code>+<code>↓</code>键，可以一键选中该行下方所有的区域（包含该行）</p><p>此方法也可用于快速删除不需要的部分，上下左右键可自己决定</p><p>例如：选中某个格子，按下<code>Ctrl</code>+<code>Shift</code>+<code>→</code>+<code>↓</code>键，可以一键选中该格子右下方的矩形区域（包含该格子）</p>`,11)])])}const x=a(d,[["render",s]]);export{_ as __pageData,x as default};
